#!/usr/bin/env node
/**
 * Bundle composition report from Metro source maps — no dependencies.
 *
 *   npx expo export --platform ios --source-maps --output-dir dist
 *   node scripts/bundle-report.mjs dist
 *
 * Decodes the source map's VLQ mappings, attributes every generated byte to
 * its original source file, then aggregates by package (or app folder).
 */
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';

const distDir = process.argv[2] ?? 'dist';
const jsDir = join(distDir, '_expo', 'static', 'js');

function findFiles(dir, predicate, out = []) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) findFiles(full, predicate, out);
    else if (predicate(full)) out.push(full);
  }
  return out;
}

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function decodeVlq(segment) {
  const values = [];
  let value = 0;
  let shift = 0;
  for (const ch of segment) {
    const digit = BASE64.indexOf(ch);
    const continuation = digit & 32;
    value += (digit & 31) << shift;
    if (continuation) {
      shift += 5;
    } else {
      const negative = value & 1;
      value >>= 1;
      values.push(negative ? -value : value);
      value = 0;
      shift = 0;
    }
  }
  return values;
}

function packageOf(source) {
  const nm = source.lastIndexOf('node_modules/');
  if (nm >= 0) {
    const rest = source.slice(nm + 'node_modules/'.length).split('/');
    return rest[0].startsWith('@') ? `${rest[0]}/${rest[1]}` : rest[0];
  }
  if (source.includes('/app/')) return 'app/ (routes)';
  if (source.includes('/src/')) {
    const after = source.slice(source.indexOf('/src/') + 5).split('/');
    return `src/${after[0]}`;
  }
  return '(other)';
}

function analyse(mapPath) {
  const map = JSON.parse(readFileSync(mapPath, 'utf8'));
  const generatedPath = mapPath.replace(/\.map$/, '');
  const generated = readFileSync(generatedPath);
  const lines = generated.toString('latin1').split('\n');

  const bytesPerSource = new Map();
  let sourceIndex = 0;
  const mappingLines = map.mappings.split(';');
  for (let line = 0; line < mappingLines.length; line += 1) {
    const segments = mappingLines[line].split(',').filter(Boolean);
    let genCol = 0;
    const cols = [];
    for (const seg of segments) {
      const [colDelta, srcDelta] = decodeVlq(seg);
      genCol += colDelta;
      if (srcDelta !== undefined) sourceIndex += srcDelta;
      cols.push({ col: genCol, source: srcDelta !== undefined ? sourceIndex : null });
    }
    const lineLength = (lines[line] ?? '').length + 1;
    for (let i = 0; i < cols.length; i += 1) {
      const end = i + 1 < cols.length ? cols[i + 1].col : lineLength;
      const size = Math.max(0, end - cols[i].col);
      const src = cols[i].source === null ? '(unmapped)' : map.sources[cols[i].source];
      bytesPerSource.set(src, (bytesPerSource.get(src) ?? 0) + size);
    }
  }

  const byPackage = new Map();
  for (const [source, bytes] of bytesPerSource) {
    const pkg = source === '(unmapped)' ? '(unmapped/runtime)' : packageOf(source);
    byPackage.set(pkg, (byPackage.get(pkg) ?? 0) + bytes);
  }
  return { generatedPath, totalBytes: generated.length, byPackage, sourceCount: map.sources.length };
}

const kb = (n) => `${(n / 1024).toFixed(1)} KB`;
const maps = findFiles(jsDir, (f) => f.endsWith('.map'));
if (maps.length === 0) {
  console.error(`No source maps under ${jsDir}. Run: npx expo export --source-maps`);
  process.exit(1);
}
for (const mapPath of maps) {
  const { generatedPath, totalBytes, byPackage, sourceCount } = analyse(mapPath);
  const platform = generatedPath.includes('/ios/') ? 'iOS' : generatedPath.includes('/android/') ? 'Android' : 'Web';
  console.log(`\n## ${platform} bundle — ${generatedPath}`);
  console.log(`Total: ${kb(totalBytes)} (pre-Hermes JS, ${sourceCount} source files)\n`);
  console.log('| Package / folder | Size | Share |');
  console.log('| --- | ---: | ---: |');
  const rows = [...byPackage.entries()].sort((a, b) => b[1] - a[1]);
  let shown = 0;
  for (const [pkg, bytes] of rows) {
    if (shown >= 25) break;
    console.log(`| ${pkg} | ${kb(bytes)} | ${((bytes / totalBytes) * 100).toFixed(1)}% |`);
    shown += 1;
  }
  const appBytes = rows.filter(([p]) => p.startsWith('src/') || p.startsWith('app/')).reduce((s, [, b]) => s + b, 0);
  console.log(`\nApplication code (src/ + app/): ${kb(appBytes)} (${((appBytes / totalBytes) * 100).toFixed(1)}%)`);
}
